import type { Option, Paper, Paragraph, Passage } from '@/types/paper';

/**
 * 2023 年 6 月大学英语六级真题（第 1–3 套）站内作答数据。
 * 检索日期：2026-11-19。
 * 来源与核验：
 * - 题面 / 选项 / 答案 / 选词填空词库 / 长篇阅读段落 / 写作范文 / 翻译参考译文：
 *   过级鸭 guojiya.cn/exam/cet6_2023_06_N/answers（整卷结构化页面，2026-11-19 逐套抓取）。
 * - 听力原文：词通英语 wordcram.com.cn/tests/cet6/listening/2023-06-N（精听页逐句英文 + 中文对照）。
 * - 答案以过级鸭所载答案表为准，选词填空 26–35、长篇阅读 36–45 的答案取自其「答案与解析」区。
 * - 听力部分给出原文，由站内合成朗读（非考试原音）；官方从不发布历年真题与听力音频。
 * - 写作范文与翻译参考译文均为机构参考版本，非唯一正确写法。
 */

/** 长篇阅读选项：由各段落生成（key=段落标记，text=段落首句，超过 60 字符截断） */
function matchOptions(paras: Paragraph[]): Option[] {
  return paras
    .filter((p): p is Paragraph & { marker: string } => Boolean(p.marker))
    .map((p) => {
      const dot = p.text.indexOf('. ');
      const first = dot > 0 ? p.text.slice(0, dot + 1) : p.text;
      const text = first.length > 60 ? `${first.slice(0, 60).replace(/[\s,;:]+$/, '')}…` : first;
      return { key: p.marker, text: `${p.marker}) ${text}` };
    });
}

/** cet6-2023-06-s1 长篇阅读段落 */
const mp_cet6_2023_06_s1: Passage = {
  id: 'cet6-2023-06-s1-mp',
  title: '长篇阅读（信息匹配）',
  paragraphs: [
    { id: 'cet6-2023-06-s1-mp-A', marker: 'A', text: `Gratitude may be more beneficial than we commonly suppose. One recent study asked participants to write a note of thanks to someone and then estimate how surprised and happy the recipient would feel—an impact that they consistently underestimated. Another study assessed the health benefits of writing thank-you notes. The researchers found that writing as few as three weekly thank-you notes over the course of three weeks improved life satisfaction, increased happy feelings and reduced symptoms of depression.` },
    { id: 'cet6-2023-06-s1-mp-B', marker: 'B', text: `While this research into gratitude is relatively new, the principles involved are anything but. Students of mine in a political philosophy course at Indiana University are reading Daniel Defoe's 300-year-old Robinson Crusoe, often regarded as the first novel published in English. Left alone on an unknown island with no apparent prospect of rescue or escape, Crusoe has much to lament (悲). But instead of giving in to despair, he makes a list of things for which he is grateful, including the fact that he is the sole survivor from the shipwreck (海难) and has been able to salvage many useful items from the wreckage.` },
    { id: 'cet6-2023-06-s1-mp-C', marker: 'C', text: `Defoe's masterpiece, which is often ranked as one of the world's greatest novels, provides a portrait of gratitude in action that is as timely and relevant today as it has ever been. It is also one with which contemporary psychology and medicine are just beginning to catch up. Simply put, for most of us, it is far more helpful to focus on the things in life for which we can express gratitude than those that incline us toward resentment and lamentation.` },
    { id: 'cet6-2023-06-s1-mp-D', marker: 'D', text: `When we focus on the things we regret, such as failed relationships, family disputes, and setbacks in career and finance, we tend to become more regretful. Conversely, when we focus on the things we are grateful for, a greater sense of happiness tends to spread through our lives. And while no one would argue for cultivating a false sense of blessedness, there is mounting evidence that counting our blessings is one of the best habits we can develop to promote mental and physical health.` },
    { id: 'cet6-2023-06-s1-mp-E', marker: 'E', text: `Gratitude has long enjoyed a privileged position in many of the world's cultural traditions. For example, some ancient Western philosophers counsel gratitude that is both enduring and complete, and some Eastern thinkers portray it as not merely an attitude but a virtue to be put into practice.` },
    { id: 'cet6-2023-06-s1-mp-F', marker: 'F', text: `Recent scientific studies support these ancient teachings. Individuals who regularly engage in gratitude exercises, such as counting their blessings or expressing gratitude to others, exhibit increased satisfaction with relationships and fewer symptoms of physical illness. And the benefits are not only psychological and physical. They may also be moral—those who practice gratitude also view their lives less materialistically and suffer from less envy.` },
    { id: 'cet6-2023-06-s1-mp-G', marker: 'G', text: `There are multiple explanations for such benefits of gratefulness. One is the fact that expressing gratitude encourages others to continue being generous, thus promoting a virtuous cycle of goodness in relationships. Similarly, grateful people may be more likely to reciprocate (回报) with acts of kindness of their own. Broadly speaking, a community in which people feel grateful to one another is likely to be a more pleasant place to live than one characterized by mutual suspicion and resentment. The beneficial effects of gratitude may extend even further. For example, when many people feel good about what someone else has done for them, they experience a sense of being lifted up, with a corresponding enhancement of their regard for humanity. Some are inspired to attempt to become better people themselves, doing more to help bring out the best in others and bringing more goodness into the world around them.` },
    { id: 'cet6-2023-06-s1-mp-H', marker: 'H', text: `Gratitude also tends to strengthen a sense of connection with others. When people want to do good things that inspire gratitude, the level of dedication in relationships tends to grow and relationships seem to last longer. And when people feel more connected, they are more likely to choose to spend their time with one another and demonstrate their feelings of affection in daily acts.` },
    { id: 'cet6-2023-06-s1-mp-I', marker: 'I', text: `Of course, acts of kindness can also foster discomfort. For example, if people feel they are not worthy of kindness or suspect that some ulterior (别有用心的) motive lies behind it, the benefits of gratitude will not be realized. Likewise, receiving a kindness can give rise to a sense of indebtedness, leaving beneficiaries feeling that they must now pay back whatever good they have received. Gratitude can flourish only if people are secure enough in themselves and sufficiently trusting to allow it to do so. Another obstacle to gratitude is often called a sense of entitlement. Instead of experiencing a benefaction (善行) as a good turn, people sometimes regard it as a mere payment of what they are owed, for which no one deserves any moral credit.` },
    { id: 'cet6-2023-06-s1-mp-J', marker: 'J', text: `There are a number of practical steps anyone can take to promote a sense of gratitude. One is simply spending time on a regular basis thinking about someone who has made a difference, or perhaps writing a thank-you note or expressing such gratitude in person. Others are found in ancient religious disciplines, such as reflecting on benefactions received from another person or actually praying for the health and happiness of a benefactor. In addition to benefactions received, it is also possible to focus on opportunities to do good oneself, whether those acted on in the past or hoped for in the future. Some people are most grateful not for what others have done for them but for chances they enjoyed to help others. In regularly reflecting on the things in his life he is grateful for, Defoe's Crusoe believes that he becomes a far better person than he would have been had he remained in the society from which he originally set out on his voyage.` },
    { id: 'cet6-2023-06-s1-mp-K', marker: 'K', text: `Reflecting on generosity and gratitude, the great basketball coach John Wooden once offered two counsels to his players and students. First, he said, "It is impossible to have a perfect day unless you have done something for someone who will never be able to repay you." In saying this, Wooden sought to promote purely generous acts, as opposed to those performed with an expectation of reward. Second, he said, "Give thanks for your blessings every day."` },
    { id: 'cet6-2023-06-s1-mp-L', marker: 'L', text: `Some faith traditions incorporate such practices into the rhythm of daily life. For example, adherents of some religions offer prayers of thanksgiving every morning before rising and every night before lying down to sleep. Others offer thanks throughout the day, such as before meals. Other less frequent special events, such as births, deaths and marriages, may also be heralded by such prayers.` },
    { id: 'cet6-2023-06-s1-mp-M', marker: 'M', text: `When Defoe depicted Robinson Crusoe making thanksgiving a daily part of his island life, he was anticipating findings in social science and medicine that would not appear for hundreds of years. Yet he was also reflecting the wisdom of religious and philosophical traditions that extend back thousands of years. Gratitude is one of the healthiest and most nourishing of all states of mind, and those who adopt it as a habit are enriching not only their own lives but also the lives of those around them.` },
  ],
};
/** cet6-2023-06-s2 长篇阅读段落 */
const mp_cet6_2023_06_s2: Passage = {
  id: 'cet6-2023-06-s2-mp',
  title: '长篇阅读（信息匹配）',
  paragraphs: [
    { id: 'cet6-2023-06-s2-mp-A', marker: 'A', text: `We're experiencing the rebirth of smallness. Farmers markets, tiny homes, and brew pubs all exemplify our love of smallness. So do charter schools, coffee shops, and local bookstores. Small is often (but not always) more affordable, healthier, and sustainable, but its finest characteristic, the one that turns charm into love, is that going small allows us to be more fully who we are.` },
    { id: 'cet6-2023-06-s2-mp-B', marker: 'B', text: `In higher education the trend is mostly in the opposite direction: Universities with 20,000 or 30,000 students are considered "mid-sized". The nation's largest university, Arizona State University, has 80,000 students on campus and aims to enroll another 100,000 students online. At the other end of the spectrum is a handful of colleges that have fewer than a hundred students on campus and no online courses: colleges such as Sterling College, Thomas More College of Liberal Arts, and Deep Springs College. These colleges are so small that they can only be called "tiny."` },
    { id: 'cet6-2023-06-s2-mp-C', marker: 'C', text: `Tiny colleges focus not just on a young person's intellect, but on the young person as a whole. Equally important, tiny colleges ask, "How can education contribute to human flourishing and the well-being of the world?" And they shape a college experience to address that question. They replace concerns about institutional growth with attention to the growth of students as fully developed participants in their communities.` },
    { id: 'cet6-2023-06-s2-mp-D', marker: 'D', text: `I've had the privilege of teaching at three different institutions of higher learning during my career — a small liberal arts college and two mid-sized public universities. I've also been profoundly disappointed in each of these institutions, and in many of my colleagues, especially when it comes to helping students and preparing them for the many responsibilities of adulthood. Administrators focus on the business of running a university, and most faculty focus on their scholarship and teaching their discipline. Little deliberate attention is given to how students mature as individuals and social beings.` },
    { id: 'cet6-2023-06-s2-mp-E', marker: 'E', text: `Having just retired from teaching at a public university, I'm now returning to my hometown of Flagstaff, Arizona, to establish a tiny college — Flagstaff College. I'm convinced there's a need for another type of education, one devoted to helping students come into their own and into this beautiful and troubled world. Young people need an education that will provide them with meaning, hope, courage, and passion, as well as information and skills. Large institutions, I believe, are particularly ill-suited to this type of education.` },
    { id: 'cet6-2023-06-s2-mp-F', marker: 'F', text: `There's no "best of" list when it comes to tiny colleges, at least not yet. But around the country people are creating new colleges that provide an alternative to small liberal arts colleges, large public universities, and online education.` },
    { id: 'cet6-2023-06-s2-mp-G', marker: 'G', text: `With only 26 students, Deep Springs is the smallest college in the country and, quite likely, the most atypical (非典型的). Located on a working cattle ranch on the California-Nevada border, Deep Springs is a private, residential, two-year college for men, committed to educating students for "a life of service to humanity." Founded by the electricity tycoon (大亨) L. L. Nunn in 1917, Deep Springs' "curriculum" revolves around academics, labor, and self-governance. In addition to their courses, students are charged with running the 155-acre ranch and overseeing the functioning of the college. Students chair both the admissions and the curriculum committees.` },
    { id: 'cet6-2023-06-s2-mp-H', marker: 'H', text: `"Living in close community with one's teachers and fellow students, and being forced to take on adult responsibilities, makes for one's growth as a person," says William Hunt, who graduated last year. "To exist for very long in a community like that, you have to get over the question of whether you're sufficiently talented or principled and get started worrying about how you can stretch yourself and your peers, how much you can manage to learn with them."` },
    { id: 'cet6-2023-06-s2-mp-I', marker: 'I', text: `Sterling College, in Craftsbury Common, Vermont, is also very small — fewer than 100 students. Unlike Deep Springs, Sterling focuses its curriculum on environmental and social justice issues, but like Deep Springs it places a high value on personal responsibility and manual labor. According to its catalog, a college education at Sterling combines "rigorous academics, roll-up-your-sleeves challenges, and good old hard work."` },
    { id: 'cet6-2023-06-s2-mp-J', marker: 'J', text: `The average tuition at a small liberal-arts college is $30,000 to $40,000 a year, not including the cost of living on campus, as compared to $8,000 to $10,000 a year for tuition alone at a public university. Of the tiny colleges, only Deep Springs doesn't charge tuition or room and board; students pay only for books and the cost of traveling to and from college. If tiny schools are to become a player on the higher education scene, they will need to find a way to be truly affordable.` },
    { id: 'cet6-2023-06-s2-mp-K', marker: 'K', text: `Doing so may not be that difficult so long as they do not pattern themselves too closely on existing norms. We've come to believe that a good college should have many academic programs and excellent facilities, posh (豪华的) dorms, an array of athletic programs, and a world-class student activity center. Imagine a good college without a climbing wall! We also have accepted the idea that college presidents, and their many vice-presidents, should be paid like their counterparts in the business world and that higher education requires an elaborate, up-to-date technology infrastructure. All of this drives up the cost of education.` },
    { id: 'cet6-2023-06-s2-mp-L', marker: 'L', text: `The "trick" to making tiny colleges affordable, if that's the right word, is simplicity. At its core, education is a human-to-human interaction. Reflecting on his own college education, President Garfield once commented that an ideal college would consist of nothing more than the legendary teacher Mark Hopkins on one end of a log and a student on the other. The economics of a tiny college, in other words, might be similar to that of a tiny house. Because it is small, a tiny house costs less to build and less to furnish, insure, and maintain. But the economic benefits of a small house don't end there. Tiny homes discourage homeowners from buying stuff that they really don't need, because there's no place to put it.` },
    { id: 'cet6-2023-06-s2-mp-M', marker: 'M', text: `I'm a late convert to the idea of tiny colleges, and I fully understand the need for many diverse types of educational institutions. Academic research and job training are important, but tiny colleges aren't suited for either. The educational needs of a complex society are themselves complex, and no single model can meet all of these needs. But I'm now convinced there's an educational need that's now going almost completely unmet: namely, the need to help young people transition into adulthood. Tiny colleges can do this better than any other type of educational institution.` },
    { id: 'cet6-2023-06-s2-mp-N', marker: 'N', text: `The ultimate justification for a tiny college is the conviction that each of us comes into our full humanity by close interaction with those who know and care for us, and that one of the basic purposes of higher education is social. Although we give lip service to the idea that a college education will make us better people, when all's said and done, we think of higher education primarily in economic terms. We've come to think of higher education as a means to make a living rather than make a life. We've also come to see higher education as a private good rather than a public one. Tiny colleges are not the answer to all of our educational requirements, but they're an answer to one of our most basic educational necessities: the need to produce thoughtful, engaged, and compassionate human beings.` },
  ],
};
